<?php require '../config/database.php';admin_required();if(isset($_GET['pago'])){$id=(int)$_GET['pago'];$pdo->beginTransaction();$pdo->prepare("UPDATE pedidos SET status='pago' WHERE id=?")->execute([$id]);$pdo->prepare("UPDATE bilhetes SET status='pago' WHERE pedido_id=?")->execute([$id]);$pdo->commit();redirect('/admin/pedidos.php');}if(isset($_GET['cancelar'])){$id=(int)$_GET['cancelar'];$pdo->beginTransaction();$pdo->prepare("UPDATE pedidos SET status='cancelado' WHERE id=?")->execute([$id]);$pdo->prepare('DELETE FROM bilhetes WHERE pedido_id=?')->execute([$id]);$pdo->commit();redirect('/admin/pedidos.php');}$ps=$pdo->query('SELECT p.*,r.titulo FROM pedidos p JOIN rifas r ON r.id=p.rifa_id ORDER BY p.id DESC')->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/css/style.css"><title>Pedidos</title></head><body><header class="top"><div class="wrap"><a href="index.php">← Painel</a></div></header><main class="wrap"><div class="box"><h1>Pedidos</h1><table><tr><th>Pedido</th><th>Cliente</th><th>Rifa</th><th>Total</th><th>Status</th><th>Ações</th></tr><?php foreach($ps as $p):?><tr><td><?=e($p['codigo'])?></td><td><?=e($p['nome'])?></td><td><?=e($p['titulo'])?></td><td>R$ <?=number_format($p['total'],2,',','.')?></td><td><?=e($p['status'])?></td><td><?php if($p['status']==='pendente'):?><a class="btn" href="?pago=<?=$p['id']?>">Pago</a> <a class="btn red" href="?cancelar=<?=$p['id']?>">Cancelar</a><?php endif;?></td></tr><?php endforeach;?></table></div></main></body></html>
